#include "Production/FoundrylineFactorySimulation.h"
#include "Inventory/FoundrylineSheetStock.h"
#include "Production/FoundrylineWorkshopLayout.h"
namespace {using Part=EFoundrylinePart;using Place=EFoundrylinePalletPlace;using Act=EFoundrylineCommerceAction;using BS=EFoundrylineBookingState;
template<typename T> bool CanOfferPart(const T& S,uint8 P){
 if(P!=uint8(Part::BentBracket)&&P!=uint8(Part::SupportChannel))return true;
 return S.Commerce.BrakeOwned&&S.Machines.ContainsByPredicate([](const auto& M){return M.Id==2;})&&S.Operators.ContainsByPredicate([](const auto& O){return O.Machine==2;});
}
}
FVector FFoundrylineFactorySimulation::PickupPosition(int32 S){return {S%2?-725.:-975.,2000.,20};}
FVector FFoundrylineFactorySimulation::CarrierPalletPosition(int32 S){return {1200,S%2?1765.:1635.,133};}
FVector FFoundrylineFactorySimulation::CarrierDock(int32 S){return CarrierPalletPosition(S)-FVector(136,0,113);}
void FFoundrylineFactorySimulation::CommerceExpense(int64 C,const FString& Label){if(C<=0)return;auto& S=State.Commerce;S.CostCents+=C;const int64 Paid=FMath::Min(S.CashCents,C);S.CashCents-=Paid;S.UnpaidCents+=C-Paid;if(Label==TEXT("Equipment operating costs")&&S.Money.Num()&&S.Money.Last().Label==Label){S.Money.Last().Cents-=C;S.Money.Last().At=S.Clock;}else S.Money.Add({S.Clock,-C,Label});if(S.Money.Num()>32)S.Money.RemoveAt(0);}
void FFoundrylineFactorySimulation::CommerceIncome(int64 C,const FString& Label){if(C<=0)return;auto& S=State.Commerce;const int64 Debt=FMath::Min(C,S.UnpaidCents);S.UnpaidCents-=Debt;S.CashCents+=C-Debt;S.Money.Add({S.Clock,C,Label});if(S.Money.Num()>32)S.Money.RemoveAt(0);}
void FFoundrylineFactorySimulation::SeedCommerce(){
 auto& C=State.Commerce;C={};C.Enabled=true;State.FloorMax.X=1600;
 FFoundrylineFactoryLane Lane;Lane.Id=State.NextId++;Lane.Kind=EFoundrylineFloorLane::Forklift;Lane.Min={-300,1450};Lane.Max={1250,1950};State.Lanes.Add(Lane);
 FFoundrylineFactoryLane Access;Access.Id=State.NextId++;Access.Kind=EFoundrylineFloorLane::Forklift;Access.Min={-1300,1450};Access.Max={-300,1800};State.Lanes.Add(Access);
 FFoundrylineFactoryLane People;People.Id=State.NextId++;People.Kind=EFoundrylineFloorLane::Pedestrian;People.Min={270,200};People.Max={370,1350};State.Lanes.Add(People);
 if(State.Routes.Num()){auto& R=State.Routes[0];R.Destinations.AddUnique(12);for(int I=0;I<4;++I){R.Sources.AddUnique(1000+I);R.Destinations.AddUnique(1000+I);}}
 for(int I=0;I<State.Drivers.Num();++I){State.Drivers[I].Parking={100,I?1100.:500.,20};State.Drivers[I].Position=State.Drivers[I].Parking;State.Drivers[I].Path.Reset();State.Drivers[I].Distance=0;}
 RefreshCommerceOffers();C.Money.Add({C.Clock,400000,TEXT("Starting working capital")});
}
void FFoundrylineFactorySimulation::RefreshCommerceOffers(){
 auto& C=State.Commerce;if(!C.Enabled)return;
 C.Orders.RemoveAll([&](const auto& O){return O.Status==EFoundrylineOrderState::Offered&&!CanOfferPart(State,O.Part);});
 int Offered=0;for(const auto& O:C.Orders)if(O.Status==EFoundrylineOrderState::Offered)++Offered;
 while(Offered<8&&C.Orders.Num()<48){const int I=C.OfferSerial++;FFoundrylineCustomerOrder O;O.Id=State.NextId++;const Part Choices[]={Part::Bracket,Part::MountingPlate,Part::GussetPlate,Part::ReinforcementPlate,Part::BentBracket,Part::SupportChannel};O.Part=uint8(Choices[I%6]);if(!CanOfferPart(State,O.Part))continue;O.Quantity=I==0?40:I%6==0?50:I%6==1?60:I%6==2?75:30;const TCHAR* Customers[]={TEXT("Hartwell Fabrication"),TEXT("Northfield Repairs"),TEXT("Red Cedar Equipment"),TEXT("Mason Agricultural"),TEXT("Alder Workshop"),TEXT("Union Conveyor Co.")};O.Customer=Customers[I%6];O.Email=I%4==3;O.Rush=I%5==4;O.AllowedMinutes=I%5==2?0:O.Rush?360:2880;O.Payment=I%4==3?EFoundrylinePayment::Upfront:I%3==1?EFoundrylinePayment::PerDelivery:EFoundrylinePayment::OnCompletion;O.UnitPriceCents=FFoundrylineCommerceCatalog::SalePrice(O.Part)*(O.Rush?140:O.Payment==EFoundrylinePayment::Upfront?90:100)/100;O.Reference=FString::Printf(TEXT("FL-%04d"),I+1);C.Orders.Add(O);++Offered;}
}
bool FFoundrylineFactorySimulation::InstallBrake(FString& E){
 auto& C=State.Commerce;if(C.BrakeOwned||C.CashCents<450000||C.UnpaidCents){E=TEXT("Press brake costs $4500; clear outstanding costs first");return false;}
 FFoundrylineFactoryMachine M;M.Id=2;M.Origin={-1900,1850,20};M.InputDock={-1364,1850,20};M.InputStock={-1500,1850,60};M.OutputDock={-1900,1336,20};M.OutputStock={-1900,1200,20};M.Auto=false;M.Making=Part::BentBracket;State.Machines.Add(M);
 for(const auto& P:FFoundrylineFactoryCatalog::DefaultPrograms())if(P.Machine==2&&(P.Part==Part::BentBracket||P.Part==Part::SupportChannel))State.Programs.Add(P);
 for(int I=0;I<2;++I){FFoundrylineFactorySlot S;S.Id=110+I;S.Part=I?Part::ReinforcementPlate:Part::Bracket;S.Position={-1500,1850,190.+I*130};S.Dock=M.InputDock;S.MachineId=2;S.bInputSupply=true;State.Slots.Add(S);for(auto& R:State.Routes){R.Sources.AddUnique(S.Id);R.Destinations.AddUnique(S.Id);R.Sources.AddUnique(2);R.Destinations.AddUnique(2);}}
 FFoundrylineFactoryLane L;L.Id=State.NextId++;L.Kind=EFoundrylineFloorLane::Forklift;L.Min={-1450,1450};L.Max={-300,1750};State.Lanes.Add(L);
 Solids.Emplace(FVector2D(-2025,1675),FVector2D(-1675,2025));Solids.Emplace(FVector2D(-1560,1642),FVector2D(-1440,2058));CommerceExpense(450000,TEXT("Press brake installation"));C.BrakeOwned=true;AddOperatorAccessLanes(2);return true;
}
bool FFoundrylineFactorySimulation::CommerceCommand(const FFoundrylineCommerceCommand& A,FString& E){
 if(!State.Commerce.Enabled||A.PlantId.IsValid()&&A.PlantId!=State.PlantId){E=TEXT("Operations unavailable for this plant");return false;}
 auto Backup=State;const auto OldSolids=Solids;auto Apply=[&]()->bool{
 auto& C=State.Commerce;auto* O=C.Orders.FindByPredicate([&](const auto& V){return V.Id==A.Id;});
 if(A.Action==Act::AcceptOrder){if(!O||O->Status!=EFoundrylineOrderState::Offered){E=TEXT("This offer is no longer available");return false;}if(!CanOfferPart(State,O->Part)){E=TEXT("This order requires an installed press brake with an assigned operator");return false;}int Active=0;for(const auto& V:C.Orders)Active+=V.Status==EFoundrylineOrderState::Accepted;if(Active>=6){E=TEXT("Finish an active order before accepting another");return false;}O->Status=EFoundrylineOrderState::Accepted;O->AcceptedAt=C.Clock;O->Deadline=O->AllowedMinutes>0?C.Clock+O->AllowedMinutes:0;if(O->Payment==EFoundrylinePayment::Upfront){O->PaidCents=O->Quantity*O->UnitPriceCents;CommerceIncome(O->PaidCents,TEXT("Customer advance / ")+O->Reference);}RefreshCommerceOffers();return true;}
 if(A.Action==Act::BuySteel){if(A.Quantity<1||A.Quantity>10||C.Bookings.Num()>=96){E=TEXT("Choose one to ten sheets");return false;}const int64 Steel=FMath::RoundToInt64(FFoundrylineSteelSheet::PoundsEach()*A.Quantity*100);if(C.UnpaidCents||C.CashCents<Steel+2500){E=TEXT("Insufficient available cash for steel and delivery");return false;}const double ETA=A.Arrival==0?C.Clock+60:A.Arrival;if(!FMath::IsFinite(ETA)||ETA<C.Clock+30||ETA>C.Clock+4320){E=TEXT("Choose a delivery at least 30 minutes from now");return false;}FFoundrylineFreightBooking B;B.Id=State.NextId++;B.Inbound=true;B.Sheets=A.Quantity;B.Carrier=FFoundrylineCommerceCatalog::PalletWeight(0,A.Quantity,FFoundrylineSteelSheet::PoundsEach())<=2000?1:2;B.Customer=TEXT("Foundry Steel Supply");B.OriginalFeeCents=2500;B.ArrivalAt=ETA;B.DispatchAt=ETA-20;C.Bookings.Add(B);CommerceExpense(Steel,TEXT("Steel sheets / ")+FString::FromInt(A.Quantity));CommerceExpense(2500,TEXT("Supplier freight booking"));return true;}
 if(A.Action==Act::AssignPickup){if(!O||O->Status!=EFoundrylineOrderState::Accepted||O->Delivered>=O->Quantity){E=TEXT("Choose an accepted, unfinished order");return false;}if(State.Pallets.ContainsByPredicate([](const auto& P){return P.Place==Place::Pickup;})||State.Jobs.ContainsByPredicate([](const auto& J){return J.DestinationPlace==Place::Pickup;})){E=TEXT("Ship the pallets already assigned to this pickup zone first");return false;}C.PickupOrder=O->Id;return true;}
 if(A.Action==Act::BookPickup){if(A.Choice<0||A.Choice>3||A.Pallets.IsEmpty()||A.Pallets.Num()>20||A.Pallets.Num()!=A.Quantities.Num()||C.Bookings.Num()>=96){E=TEXT("Select a vehicle and at least one staged pallet");return false;}auto* Order=C.Orders.FindByPredicate([&](const auto& V){return V.Id==C.PickupOrder;});if(!Order||Order->Status!=EFoundrylineOrderState::Accepted){E=TEXT("Assign an active customer order to this zone");return false;}const auto Carrier=FFoundrylineCommerceCatalog::Carrier(A.Choice);if(!FMath::IsFinite(A.Arrival)||A.Arrival<C.Clock+Carrier.LeadMinutes+1||A.Arrival>C.Clock+4320){E=TEXT("Choose an arrival after the carrier's lead time");return false;}if(C.UnpaidCents||C.CashCents<Carrier.FeeCents){E=TEXT("Insufficient available cash for this pickup fee");return false;}FFoundrylineFreightBooking B;B.Id=State.NextId++;B.OrderId=Order->Id;B.Customer=Order->Customer;B.Carrier=A.Choice;B.ArrivalAt=A.Arrival;B.DispatchAt=B.ArrivalAt-Carrier.LeadMinutes;B.OriginalFeeCents=Carrier.FeeCents;TSet<int> Seen;int Spaces=0,Quantity=0;double Weight=0;
 for(int I=0;I<A.Pallets.Num();++I){auto* P=State.Pallets.FindByPredicate([&](const auto& V){return V.Id==A.Pallets[I];});if(!P||P->Place!=Place::Pickup||P->OrderId!=Order->Id||P->BookingId||P->Reserved||P->Quantity!=A.Quantities[I]||Seen.Contains(P->Id)){E=TEXT("A selected pallet changed or is already booked; refresh the list");return false;}Seen.Add(P->Id);Spaces+=FFoundrylineCommerceCatalog::PalletSpaces(uint8(P->Part));Weight+=FFoundrylineCommerceCatalog::PalletWeight(uint8(P->Part),P->Quantity,P->UnitLb);Quantity+=P->Quantity;B.Manifest.Add({P->Id,uint8(P->Part),P->Quantity,P->UnitLb});}
 int Committed=Order->Delivered;for(const auto& Existing:C.Bookings)if(!Existing.Inbound&&Existing.OrderId==Order->Id&&Existing.Status!=BS::Delivered)for(const auto& Item:Existing.Manifest)Committed+=Item.Quantity;
 if(Spaces>Carrier.Spaces||Weight>Carrier.PayloadLb+.01||Committed+Quantity>Order->Quantity){E=TEXT("Selected pallets exceed vehicle capacity or the order's remaining quantity");return false;}
 for(int Id:A.Pallets)State.Pallets.FindByPredicate([&](const auto& P){return P.Id==Id;})->BookingId=B.Id;C.Bookings.Add(B);CommerceExpense(Carrier.FeeCents,FString(Carrier.Name)+TEXT(" / pickup booked"));return true;}
 if(A.Action==Act::Reschedule){auto* B=C.Bookings.FindByPredicate([&](const auto& V){return V.Id==A.Id;});if(!B||B->Status!=BS::Booked||C.Clock>=B->DispatchAt){E=TEXT("The carrier is already travelling; this booking is locked");return false;}const auto Spec=FFoundrylineCommerceCatalog::Carrier(B->Carrier);const double Lead=B->Inbound?20:Spec.LeadMinutes;const int64 Fee=B->OriginalFeeCents/2;if(!FMath::IsFinite(A.Arrival)||A.Arrival<C.Clock+Lead+1||A.Arrival>C.Clock+4320||C.UnpaidCents||C.CashCents<Fee){E=TEXT("Choose a valid arrival and allow for the rebooking fee");return false;}B->ArrivalAt=A.Arrival;B->DispatchAt=A.Arrival-Lead;CommerceExpense(Fee,TEXT("Carrier rebooking / 50% original fee"));return true;}
 if(A.Action==Act::DriverPriority){auto* D=State.Drivers.FindByPredicate([&](const auto& V){return V.Id==A.Id;});if(!D||A.Choice<0||A.Choice>2||A.Quantity<0||A.Quantity>2||D->Priorities.Num()!=3){E=TEXT("Choose a driver task priority");return false;}const int Old=D->Priorities[A.Choice];for(auto& P:D->Priorities)if(P==A.Quantity)P=Old;D->Priorities[A.Choice]=A.Quantity;return true;}
 if(A.Action==Act::BuyBrake)return InstallBrake(E);
 if(A.Action==Act::BuyForklift){if(C.UnpaidCents||C.CashCents<120000||State.Drivers.Num()>=2){E=TEXT("A second forklift costs $1200; this starter has two parking stalls");return false;}if(!AddDriver(1,E,false))return false;auto& D=State.Drivers.Last();D.Parking={100,1100,20};D.Position=D.Parking;CommerceExpense(120000,TEXT("Forklift purchase"));return true;}
 E=TEXT("Unknown operations request");return false;};
 if(!Apply()){State=MoveTemp(Backup);Solids=OldSolids;return false;}++State.Revision;return true;
}
